True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marked = set()
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            marked.update((r, c) for c in range(w))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            marked.update((r, c) for r in range(h))
    for r, c in marked:
        out[r][c] = 2
    return out
